//
// MLPerf Tiny ResNet-8 inference + fused Grad-CAM on GeMMX, generated by
// data/resnet8.py (real pretrainedResnet_quant weights, real CIFAR-10 image):
//  - DMA core: places the 32x32x3 input into the padded C8HW8 input buffer
//    (one 2-D DMA per row, 3-byte pixels into 8-byte channel slots), streams
//    the conv weight / bias tiles from L3 one step ahead into two buffers,
//    refills activation borders with the zero point when a slot changes shape;
//  - core 0: one GeMMX launch per step, configured by generated delta CSR
//    writes; picks the predicted class, writes alpha (its FC row) and the
//    zero-point bias, and finishes Grad-CAM (ReLU + Q15 normalisation);
//  - logits, final feature map and the class activation map are compared
//    byte for byte with the emulator.

#include <stdint.h>

#include "snrt.h"             // write_csr, used by the generated cfg_* in data.h
#include "snax-gemmx-lib.h"
#include "data.h"

enum { POST_NONE = 0, POST_FILL = 1, POST_ALPHA = 2, POST_CAM = 3 };
#define N_PHASES 5

int main() {
    uint8_t *l1 = (uint8_t *)snrt_l1_next();
    const int core0 = snrt_global_core_idx() == 0;
    const int dm = snrt_is_dm_core();
    if (dm) {
        snrt_dma_start_1d(l1, prog_image, PROG_IMAGE_BYTES);
        snrt_dma_wait_all();
    }
    snrt_cluster_hw_barrier();

    uint32_t phase_cyc[N_PHASES] = {0}, cfg = 0, run = 0, core_ops = 0, t_in = 0;
    int pred = -1;
    uint32_t t_start = snrt_mcycle();
    if (dm) {
        uint32_t a = snrt_mcycle();
        // pixel (y, x) -> PROG_IN_OFF + (y+1)*Wp*8 + (x+8)*8, channels 0..2
        for (int y = 0; y < 32; y++)
            snrt_dma_start_2d(l1 + PROG_IN_OFF + (y + 1) * PROG_IN_WP * 8 + 64,
                              prog_img + y * 96, 3, 8, 3, 32);
        snrt_dma_start_1d(l1 + prog_blob_dst[PROG_FIRST_BLOB],
                          prog_params + prog_blob_off[PROG_FIRST_BLOB],
                          prog_blob_len[PROG_FIRST_BLOB]);
        snrt_dma_wait_all();
        t_in = snrt_mcycle() - a;
    }
    snrt_cluster_hw_barrier();

    for (int s = 0; s < PROG_N_STEPS; s++) {
        const rstep_t *st = &prog_steps[s];
        uint32_t a = snrt_mcycle();
        // Pre-ops (before the launch): border refill, alpha placement.
        if (st->post == POST_FILL) {
            if (dm) snrt_dma_memset(l1 + st->a, 0x80, st->b);
            snrt_cluster_hw_barrier();
        } else if (st->post == POST_ALPHA) {
            if (core0) {
                const int8_t *lg = (const int8_t *)(l1 + st->a);
                int8_t best = -128;
                for (int i = 0; i < 10; i++) {          // logits: row 0 of 2 blocks
                    int8_t v = lg[(i / 8) * 64 + (i % 8)];
                    if (v > best || pred < 0) { best = v; pred = i; }
                }
                int8_t *al = (int8_t *)(l1 + st->b);    // B blocks kt=0..7, column 0
                int32_t sum = 0;
                for (int k = 0; k < 64; k++) {
                    int8_t w = prog_fc[pred * 64 + k];
                    al[(k / 8) * 64 + (k % 8)] = w;
                    sum += w;
                }
                int32_t *ct = (int32_t *)(l1 + st->c);
                for (int i = 0; i < 64; i++) ct[i] = -st->d * sum;
            }
            snrt_cluster_hw_barrier();
        }
        if (st->post == POST_FILL || st->post == POST_ALPHA) {
            if (core0) {
                core_ops += snrt_mcycle() - a;
                phase_cyc[st->phase] += snrt_mcycle() - a;
            }
            a = snrt_mcycle();
        }
        if (dm && st->prefetch >= 0)
            snrt_dma_start_1d(l1 + prog_blob_dst[st->prefetch],
                              prog_params + prog_blob_off[st->prefetch],
                              prog_blob_len[st->prefetch]);
        if (core0 && st->launch >= 0) {
            uint32_t b0 = snrt_mcycle();
            cfg_fns[st->launch]((uint32_t)l1);
            uint32_t b1 = snrt_mcycle();
            set_gemmx_streamer_start();
            set_gemmx_start();
            wait_gemmx_and_streamer();
            uint32_t b2 = snrt_mcycle();
            cfg += b1 - b0;
            run += b2 - b1;
            phase_cyc[st->phase] += b2 - b0;
        }
        if (dm) snrt_dma_wait_all();
        snrt_cluster_hw_barrier();
        if (st->post == POST_CAM) {
            uint32_t c0 = snrt_mcycle();
            if (core0) {
                // cam[h*8+w] = column 0 of D32 block h, row w; ReLU + Q15.
                const int32_t *d = (const int32_t *)(l1 + st->a);
                int32_t *cam = (int32_t *)(l1 + st->b);
                int32_t mx = 0;
                for (int h = 0; h < 8; h++)
                    for (int w = 0; w < 8; w++) {
                        int32_t v = d[h * 64 + w * 8];
                        v = v < 0 ? 0 : v;
                        cam[h * 8 + w] = v;
                        if (v > mx) mx = v;
                    }
                uint32_t inv = mx > 0 ? (1u << 31) / (uint32_t)mx : 0;
                for (int i = 0; i < 64; i++)
                    cam[i] = (int32_t)(((uint64_t)(uint32_t)cam[i] * inv) >> 16);
            }
            snrt_cluster_hw_barrier();
            if (core0) {
                core_ops += snrt_mcycle() - c0;
                phase_cyc[st->phase] += snrt_mcycle() - c0;
            }
        }
    }
    uint32_t t_end = snrt_mcycle();
    snrt_cluster_hw_barrier();

    uint32_t err = 0;
    if (dm) printf("[DMA] input placement + first tile: %u cycles\n", t_in);
    if (core0) {
        printf("[TOTAL] %u cycles, %d steps: config=%u run=%u core-ops=%u, predicted class %d\n",
               t_end - t_start, PROG_N_STEPS, cfg, run, core_ops, pred);
        for (int p = 0; p < N_PHASES; p++)
            if (phase_cyc[p]) printf("  %-8s %u\n", prog_phase_names[p], phase_cyc[p]);
        for (int c = 0; c < PROG_N_CHECKS; c++) {
            const uint8_t *got = l1 + prog_check_off[c];
            const uint8_t *exp = prog_expected + prog_check_pos[c];
            uint32_t e = 0;
            for (int j = 0; j < prog_check_len[c]; j++) e += got[j] != exp[j];
            printf("check %-7s %s (%u/%d bytes differ)\n", prog_check_names[c],
                   e ? "FAIL" : "OK", e, prog_check_len[c]);
            err += e;
        }
    }
    snrt_cluster_hw_barrier();
    return err;
}
